def decide(recipient_reputation, round_num, my_history):
    # Compute own donation rate
    if len(my_history) == 0:
        own_donate_fraction = 0.5
    else:
        own_donate_fraction = sum(my_history) / len(my_history)
    # Base threshold adjusts with own generosity: if we donate a lot, threshold is lower (more forgiving)
    # Additionally, early rounds (first 10) are more forgiving to encourage cooperation.
    base_threshold = 0.2 + 0.4 * (1 - own_donate_fraction)
    if round_num <= 10:
        base_threshold -= 0.2
    # Clamp to a reasonable range
    threshold = max(0.0, min(1.0, base_threshold))
    return recipient_reputation > threshold

